package dev.kubejseditor.client;

import mezz.jei.api.gui.IRecipeLayoutDrawable;
import dev.kubejseditor.recipe.CanvasFit;
import dev.kubejseditor.runtime.EditorRuntime;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.components.Button;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.network.chat.Component;
import net.minecraft.world.item.ItemStack;
import net.neoforged.neoforge.fluids.FluidStack;
import java.util.*;

/** Display-only/composite recipes still have a workbench, without inventing writable native IDs. */
public final class JeiDisplayScreen extends Screen {
    private final Screen parent;private final IRecipeLayoutDrawable<?> layout;private final JeiRecipeSources.Source source;private CanvasFit fit;private List<net.minecraft.util.FormattedCharSequence> lines=List.of();private int offset;
    public JeiDisplayScreen(Screen parent,IRecipeLayoutDrawable<?> layout,JeiRecipeSources.Source source){super(Component.literal("强制兼容 · "+layout.getRecipeCategory().getTitle().getString()));this.parent=parent;this.layout=CompatJeiLayouts.reference(layout);this.source=source;}
    public static void open(Screen parent,IRecipeLayoutDrawable<?> layout){var source=JeiRecipeSources.resolve(layout);if(source.id()!=null&&!source.notice().isBlank()){Minecraft.getInstance().setScreen(new net.minecraft.client.gui.screens.ConfirmScreen(accepted->{if(accepted)openResolved(parent,layout,source);else Minecraft.getInstance().setScreen(parent);},Component.literal("确认原始配方"),Component.literal(source.notice()+"\n来源："+source.id()),Component.literal("编辑原来源"),Component.literal("取消")));return;}openResolved(parent,layout,source);} private static void openResolved(Screen parent,IRecipeLayoutDrawable<?> layout,JeiRecipeSources.Source source){if(source.id()!=null){JeiRecipeSources.capture(layout,source.id());var nativeRecipe=Optional.ofNullable(dev.kubejseditor.runtime.EditorRuntime.recipe(source.id().toString()));if(nativeRecipe.isPresent()&&nativeRecipe.get().data()!=null){WorkspaceScreen.openRecipe(source.id().toString(),parent);return;}Minecraft.getInstance().setScreen(new JeiDisplayScreen(parent,layout,new JeiRecipeSources.Source(null,nativeRecipe.map(r->r.error()).orElse("实际来源已卸载，请重新打开 JEI"))));}else Minecraft.getInstance().setScreen(new JeiDisplayScreen(parent,layout,source));}
    @Override protected void init(){int work=Math.max(280,width-112),right=work*3/5;CompatDiagnostics.unavailable(layout.getRecipeCategory().getRecipeType().getUid()+" / "+layout.getRecipe().getClass().getName(),source.reason());fit=CanvasFit.centered(16,62,right-30,Math.max(40,height-128),layout.getRecipeCategory().getWidth(),layout.getRecipeCategory().getHeight(),2);var text=new ArrayList<String>();text.add("只读展示："+source.reason());text.add("JEI 分类："+layout.getRecipeCategory().getRecipeType().getUid());text.add("展示对象："+layout.getRecipe().getClass().getName());
        for(var slot:layout.getRecipeSlotsView().getSlotViews()){var values=slot.getAllIngredients().map(v->describe(v.getIngredient())).toList();if(!values.isEmpty())text.add((slot.getRole()==mezz.jei.api.recipe.RecipeIngredientRole.OUTPUT?"输出格":slot.getRole()==mezz.jei.api.recipe.RecipeIngredientRole.CATALYST?"催化剂":"输入格")+" · "+slot.getSlotName().orElse("")+"："+String.join(" / ",values));}
        var value=layout.getRecipe();if(value.getClass().isRecord())for(var field:value.getClass().getRecordComponents())try{text.add("展示字段 "+CompatLabels.name(new dev.kubejseditor.recipe.compat.CompatDefinition.Field("/"+field.getName(),field.getName(),dev.kubejseditor.recipe.compat.CompatDefinition.Kind.JSON,dev.kubejseditor.recipe.compat.CompatDefinition.Role.PARAMETER))+"："+describe(field.getAccessor().invoke(value)));}catch(Exception e){text.add(field.getName()+"：无法读取");}
        lines=new ArrayList<>();for(String line:text)for(var formatted:font.split(Component.literal(line),Math.max(80,work-right-22)))lines.add(formatted);
        var choose=Button.builder(Component.literal(source.candidates().isEmpty()?"选择实际数据":"确认原生来源"),b->{if(source.candidates().isEmpty())GenericDataBrowser.open(this,layout);else minecraft.setScreen(new ChoiceScreen(this,"确认来源（核对原始 JSON 后进入编辑）",source.candidates().stream().map(id->new ChoiceScreen.Choice(id.toString(),()->{JeiRecipeSources.capture(layout,id);CompatibilityScreenOpen.open(this,id.toString());},id.toString())).toList()));}).bounds(16,36,120,20).build();choose.active=Minecraft.getInstance().hasSingleplayerServer()&&!EditorRuntime.locked();addRenderableWidget(choose);
        addRenderableWidget(Button.builder(Component.literal("模组全局机器配置"),b->CompatConfigScreen.open(this,layout.getRecipeCategory().getRecipeType().getUid().getNamespace())).bounds(142,36,142,20).build());addRenderableWidget(Button.builder(Component.literal("适配说明"),b->minecraft.setScreen(new TextScreen(this,"只读适配说明",CompatDiagnostics.read()))).bounds(290,36,88,20).build());addRenderableWidget(Button.builder(Component.literal("返回"),b->onClose()).bounds(work-80,height-30,64,20).build());}
    private static String describe(Object value){if(value instanceof ItemStack item)return item.getHoverName().getString()+" ×"+item.getCount()+" "+item.getComponents();if(value instanceof FluidStack fluid)return fluid.getHoverName().getString()+" "+fluid.getAmount()+" mB";if(value instanceof Collection<?> list)return list.stream().limit(64).map(JeiDisplayScreen::describe).toList().toString();return String.valueOf(value);}
    @Override public void render(GuiGraphics g,int x,int y,float partial){int work=Math.max(280,width-112),right=work*3/5;g.fill(0,0,width,height,0xFF0B121A);g.drawString(font,title,16,14,0xFF7DD3FC,false);if(WorkspaceJeiPlugin.runtime==null){g.drawString(font,"JEI 正在重载，原始展示稍后恢复",16,72,0xFFFFCC88,false);super.render(g,x,y,partial);return;}g.enableScissor(12,60,right-8,height-46);g.pose().pushPose();g.pose().translate(fit.x(),fit.y(),0);g.pose().scale((float)fit.scale(),(float)fit.scale(),1);try{layout.drawRecipe(g,(int)fit.localX(x),(int)fit.localY(y));}catch(Throwable e){CompatDiagnostics.failure("display",title.getString(),e);}g.pose().popPose();g.disableScissor();int count=Math.max(1,(height-90)/11);offset=Math.min(offset,Math.max(0,lines.size()-count));for(int i=offset;i<Math.min(lines.size(),offset+count);i++)g.drawString(font,lines.get(i),right,64+(i-offset)*11,0xFFCBD5E1,false);super.render(g,x,y,partial);}
    @Override public boolean mouseScrolled(double x,double y,double dx,double dy){offset=Math.max(0,offset-(int)dy*3);return true;}
    @Override public void onClose(){minecraft.setScreen(parent);}
    @Override public void renderBackground(GuiGraphics g,int x,int y,float partial){}
    @Override public boolean isPauseScreen(){return false;}
}
